  foo: string;
  x?: integer;
  y?: integer;
};

type Output = {
  bar: string;
};

template.schema:
type Input = {
  firstName: string;
  lastName: string;
  fooToBar?: {[name: string]: integer};
};

type Output = {
  x: integer;
};

